const text=(v,l)=>{if(v==null||String(v).trim()==='')throw new TypeError(`${l} is required`);return String(v).trim()};
export function createContact({id,type='person',name,channels=[],addresses=[],identifiers=[],tags=[],metadata={}}={}){if(!['person','organization'].includes(type))throw new TypeError('contact type must be person or organization');return Object.freeze({id:text(id,'contact id'),type,name:text(name,'contact name'),channels:Object.freeze(channels.map(normalizeChannel)),addresses:Object.freeze(addresses.map(a=>Object.freeze({...a}))),identifiers:Object.freeze(identifiers.map(i=>Object.freeze({type:text(i.type,'identifier type'),value:text(i.value,'identifier value')}))),tags:Object.freeze([...new Set(tags.map(String))]),metadata:Object.freeze({...metadata})})}
function normalizeChannel(c){const type=text(c?.type,'channel type'),value=text(c?.value,'channel value');return Object.freeze({type,value,label:c.label==null?null:String(c.label),primary:Boolean(c.primary)})}
export function addContactChannel(contact,channel){const next=normalizeChannel(channel);const channels=contact.channels.map(c=>next.primary?Object.freeze({...c,primary:false}):c);return Object.freeze({...contact,channels:Object.freeze([...channels,next])})}
export function mergeContact(contact,patch={}){return createContact({...contact,...patch,id:contact.id,channels:patch.channels??contact.channels,addresses:patch.addresses??contact.addresses,identifiers:patch.identifiers??contact.identifiers,tags:patch.tags??contact.tags,metadata:{...contact.metadata,...patch.metadata}})}
